bool muse_avatar_expand_frame(unsigned frame, uint16_t *dst) {
    if (frame >= 30 || dst == NULL) return false;
    const uint8_t *run = kFrames[frame];
    unsigned at = 0;
    while (at < 4096) {
        unsigned count = run[0];
        uint16_t colour = kPalette[run[1]];
        run += 2;
        for (unsigned i = 0; i < count && at < 4096; ++i) dst[at++] = colour;
    }
    return true;
}
